import Observation
import SwiftUI
#if canImport(UIKit)
import UIKit
#else
import AppKit
#endif

/// The app icons to choose from in Settings → Appearance. The icon sets are generated by
/// design/AppIcon/make-app-icons.py and listed in project.yml (ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES).
public enum AppIconChoice: String, CaseIterable, Identifiable, Sendable {
    case `default`, black, midnight, mint, grape, sunset, graphite, light

    public var id: String { rawValue }

    public var title: String {
        switch self {
        case .default: "Default"
        case .black: "Black"
        case .midnight: "Midnight"
        case .mint: "Mint"
        case .grape: "Grape"
        case .sunset: "Sunset"
        case .graphite: "Graphite"
        case .light: "Light"
        }
    }

    /// The alternate icon set's name; nil for the primary icon.
    public var iconName: String? { self == .default ? nil : "AppIcon-\(title)" }

    /// Unknown names (an icon removed in a later version) fall back to the default.
    public init(iconName: String?) {
        self = Self.allCases.first { $0.iconName == iconName } ?? .default
    }

    var previewName: String { "app-icon-\(rawValue)" }

    var preview: Image { Image(previewName, bundle: .module) }

    /// For tests: the preview ships in the asset catalog.
    var hasPreview: Bool {
        #if canImport(UIKit)
        UIImage(named: previewName, in: .module, compatibleWith: nil) != nil
        #else
        Bundle.module.image(forResource: previewName) != nil
        #endif
    }
}

/// Changes the app's icon on this device.
@MainActor
public protocol AppIconSwitching: AnyObject {
    var currentName: String? { get }
    var supportsAlternateIcons: Bool { get }
    func setIcon(_ name: String?) async throws
}

@MainActor @Observable
public final class AppIconModel {
    public private(set) var current: AppIconChoice
    public private(set) var errorMessage: String?
    public var isAvailable: Bool { switcher.supportsAlternateIcons }

    @ObservationIgnored private let switcher: any AppIconSwitching

    public init(switcher: (any AppIconSwitching)? = nil) {
        let switcher = switcher ?? SystemAppIconSwitcher.shared
        self.switcher = switcher
        current = AppIconChoice(iconName: switcher.currentName)
    }

    public func choose(_ choice: AppIconChoice) async {
        guard choice != current else { return }
        errorMessage = nil
        do {
            try await switcher.setIcon(choice.iconName)
            current = choice
        } catch {
            errorMessage = "Couldn't change the icon. Try again."
        }
    }
}

#if canImport(UIKit)
/// iPhone and iPad: the system's alternate app icons (iOS shows its own "You have changed the icon" note).
public final class SystemAppIconSwitcher: AppIconSwitching {
    public static let shared = SystemAppIconSwitcher()
    public var currentName: String? { UIApplication.shared.alternateIconName }
    public var supportsAlternateIcons: Bool { UIApplication.shared.supportsAlternateIcons }
    public func setIcon(_ name: String?) async throws {
        try await UIApplication.shared.setAlternateIconName(name)
    }
}
#else
/// Mac: macOS has no alternate app icons, so the choice is the Dock icon while ByteCache runs
/// (Finder and Launchpad keep the default). It's remembered and put back at every launch.
public final class SystemAppIconSwitcher: AppIconSwitching {
    public static let shared = SystemAppIconSwitcher()
    private static let key = "macAppIcon"
    private let defaults = UserDefaults.standard

    public var currentName: String? { defaults.string(forKey: Self.key) }
    public var supportsAlternateIcons: Bool { true }

    public func setIcon(_ name: String?) async throws {
        defaults.set(name, forKey: Self.key)
        apply()
    }

    /// Call once at launch.
    public func apply() {
        let choice = AppIconChoice(iconName: currentName)
        NSApplication.shared.applicationIconImage = choice == .default ? nil : Bundle.module.image(forResource: choice.previewName)
    }
}
#endif
